CREATE OR REPLACE FUNCTION public.has_paid_bell(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.account_allowed(_user) AND (EXISTS(SELECT 1 FROM public.prime99_payments WHERE user_id=_user AND payment_purpose='membership' AND payable_amount=100 AND plan_months=3 AND status='approved' AND received_at<=now() AND ends_at>now()) OR EXISTS(SELECT 1 FROM public.membership_access a JOIN public.membership_requests r ON r.id=a.request_id AND r.user_id=a.user_id WHERE a.user_id=_user AND a.feature_scope='all' AND a.revoked_at IS NULL AND a.starts_at<=now() AND a.ends_at>now() AND r.amount=100 AND r.vehicle_plan_months=3 AND r.status='approved')) $$;
DO $$ DECLARE r record; def text; BEGIN FOR r IN SELECT p.oid FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname IN ('ring_service','ring_vehicle_board','request_own_bell_notice','request_service') LOOP SELECT pg_get_functiondef(r.oid) INTO def; def:=regexp_replace(def,'\mBEGIN\M','BEGIN IF auth.uid() IS NULL OR (NOT public.has_paid_bell(auth.uid()) AND NOT public.has_role(auth.uid(),''admin'')) THEN RAISE EXCEPTION ''SUBSCRIPTION_REQUIRED''; END IF;','i'); EXECUTE def; END LOOP; END $$;
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.admin_membership_access(uuid,boolean)'::regprocedure) INTO def; def:=replace(def,'IF _enable THEN INSERT','IF _enable AND NOT public.has_paid_bell(_user) THEN RAISE EXCEPTION ''APPROVED_SUBSCRIPTION_REQUIRED''; END IF; IF _enable THEN INSERT'); EXECUTE def; END $$;